  for(const [label,value] of [['Максимум здоровья',stats.maxHP-before.maxHP],['Защита',stats.armor-before.armor],['Вместимость Хрома',stats.chrome.capacity-before.chrome.capacity]])if(value)permanent.push(sign(value)+' · '+label);
