 function nodeTargets(m){const points={head:[50,13.39],nerves:[52,22.74],arms:[36.8,36.29],torso:[53.4,37.9],skin:[45.8,52.58],legs:[55.6,74.2]};return '<div class="chrome-node-controls">'+zones.filter(([id])=>id!=='system').map(([id,label])=>'<button type="button" class="chrome-node-target" tabindex="-1" data-chrome-zone="'+id+'" aria-label="'+label+': '+m.counts[id]+' установлено" style="left:'+points[id][0]+'%;top:'+points[id][1]+'%"></button>').join('')+'</div>';}
 function body(m,s){return `<section class="chrome-panel chrome-body" aria-labelledby="chrome-body-title"><header class="chrome-panel-head"><h2 id="chrome-body-title">Схема тела</h2><small>Фронтальная проекция</small></header><div class="chrome-body-stage">${bodyArt()}${nodeTargets(m)}<div class="chrome-zone-controls" aria-label="Зоны тела">${zones.filter(([id])=>id!=='system').map(([id,label,i])=>`<button type="button" class="chrome-zone chrome-zone-${id} ${m.counts[id]?'has-installations':''}" data-chrome-zone="${id}" aria-pressed="${s.zone===id}" aria-label="${label}: ${m.counts[id]} установлено">${icon(i)}<span><strong>${label}</strong><small>${m.counts[id]} установлено</small></span></button>`).join('')}</div></div><button class="chrome-system-zone" data-chrome-zone="system" aria-pressed="${s.zone==='system'}">${icon('chrome')}<span>Системные</span><b>${m.counts.system}</b></button></section>`;}
