 function list(m,s,rows){return `<section class="chrome-panel chrome-installed" aria-labelledby="chrome-installed-title"><header class="chrome-panel-head"><h2 id="chrome-installed-title">Установленные импланты</h2><small>Всего: ${m.rows.length}</small></header>${filters(m,s)}<div class="chrome-implant-list">${rows.map(row=>`<button type="button" class="chrome-implant ${s.selected===row.id?'is-selected':''}" data-chrome-select="${h(row.id)}" aria-pressed="${s.selected===row.id}">${art(row,'chrome-item-icon')}<span class="chrome-implant-copy"><strong>${h(name(row.item))}</strong><small>${h(zones.find(([id])=>id===row.zone.id)[1])}${row.item.subtype?' · '+h(row.item.subtype):''}</small></span><span class="chrome-slot-label">${row.slots}<small> сл.</small></span><span class="chrome-arrow" aria-hidden="true">›</span></button>`).join('')||`<div class="chrome-empty">${icon('chrome')}<h3>${m.rows.length?'В этой зоне нет установок':'Импланты не установлены'}</h3>${m.rows.length?'':'<p>Установка и извлечение выполняются через снаряжение</p>'}<button type="button" data-chrome-inventory>Открыть снаряжение</button></div>`}</div></section>`;}
